"use client";
import { ArtemisScope } from "./artemis-scope";
import Variant0 from "./components/model-picker/variants/01-provider-catalog";
import Variant1 from "./components/model-picker/variants/02-provider-rail";
const variants = {"provider-catalog": Variant0,"provider-rail": Variant1};
export interface ArtemisModelPickerProps { className?: string; variant?: "provider-catalog" | "provider-rail"; }
export function ArtemisModelPicker({ className, variant = "provider-catalog" }: ArtemisModelPickerProps) { const View = variants[variant]; return <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}><div className="art:flex art:w-full art:justify-center"><View/></div></ArtemisScope>; }
